/// <summary>
/// TMSEngine move it in batch class
/// <c>METTMSEngineController</c> Run the TMSEngine in batch for the given transferId
/// </summary>
class METTMSEngineController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates new instance of <c>METTMSEngineController</c>
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(METTMSEngineService));
    this.parmMethodName(methodStr(METTMSEngineService, processTMSEngineBacklog));

    this.parmDialogCaption("@MET:TriggerTMSEngine");
}

/// <summary>
/// Sets the caption of the job
/// </summary>
/// <returns>Caption of the job</returns>
public ClassDescription caption()
{
    return "@MET:TriggerTMSEngine";
}

/// <summary>
/// Method which is run while calling the corresponding menu item
/// </summary>
/// <param name = "args">Arguments passed from the menu item</param>
public static void main(Args args)
{
    METTMSEngineController controller;

    controller = new METTMSEngineController();
    controller.startOperation();
}
